demo-js.async-demo.js:
// async-await: Promise 객체를 좀 더 쉽고 편하게 사용할 수 있게 해주는 문법
// 즉, 비동기 처리가 쉽다!

// async 함수
// _____ function f() {}: 일반 함수
// async function f() {}: async 함수

// async의 첫 번째 기능: Promise 객체 반환
async function f() {
    return '완료'; // 자동으로 Promise 객체를 반환 중
    // = return Promise.resolve('완료');
    // async 함수는 무조건 Promise 객체를 반환한다.
    // 만약 반환값이 Promise 객체가 아니라면, 자동으로 Promise.resolve()로 감싸서 반환한다.
};

f().then(
    (result) => {
        console.log("promise resolve: ", result);
    },
    (error) => {
        console.error("promise reject: ", error);
    }
);

demo-js.await-demo.js:
// await은 async 함수 안에서만 동작한다
// await은 Promies 객체.then()을 좀 더 쉽게 사용할 수 있는 방법

// async의 두 번째 기능: Promise 객체가 일이 끝날 때까지 기다릴 수 있는 공간을 제공한다! = await
async function f() {
    // promise 객체 한 개당 => query 하나
    let promise1 = new Promise((resolve, reject) => {
        setTimeout(() => {
            resolve('첫 번째 쿼리');
        }, 3000);
    });
    let result1 = await promise1;
    console.log(result1);

    let promise2 = new Promise((resolve, reject) => {
        setTimeout(() => {
            resolve('두 번째 쿼리 with ' + result1);
        }, 3000);
    });

    let result2 = await promise2;
    console.log(result2);

    let promise3 = new Promise((resolve, reject) => {
        setTimeout(() => {
            resolve('세 번째 쿼리 with ' + result2);
        }, 3000);
    });

    let result3 = await promise3;
    console.log(result3);
};

f();

